// This file is not generated by Speakeasy. It decides which values --dry-run
// and --debug hide when they print request and response bodies.
//
// The generated rule hid a fixed list of lowercase names: password, secret,
// token, api_key and a few more. The Voiceflow API names its fields in
// camelCase, so most of the secrets it carries printed in full: apiKeySecret,
// keySecret, secretKey, oauthSecretKey, webhookSecret, webhookSecretKey and
// authHeaderValue in integration credentials, a secret's value in secret
// create and set-value, and Authorization values in API tool and MCP server
// headers. Coding agents keep stderr in their transcripts, so a dry run or a
// debug run leaked them.
//
// The rule is fitted to a survey of all 868 property names in the OpenAPI spec
// (.speakeasy/out.openapi.yaml):
//
//   - Names are compared without case or separators, so apiKey, api_key and
//     API-KEY are one name. A name that ends in secret, secretkey, password,
//     token, apikey or privatekey holds a secret, which covers every name the
//     generated list had. Counts such as maxTokens end in "tokens", and
//     identifiers such as accountSid, apiKeySid, keyId and accessTokenID end in
//     none of them, so they stay visible.
//   - credentials is hidden whole. It holds an integration's secrets, some
//     under names, such as authHeaderValue, that no general rule would catch.
//   - A {key, value} pair, the shape of API tool and MCP server headers and of
//     query parameters, hides its value when the key names a credential, such
//     as Authorization or X-Api-Key.
//   - The secret endpoints carry the secret in generic fields: defaultValue on
//     create and value on set-value. Those are hidden on requests to them.
//
// Booleans, numbers and null are never hidden: hasPassword says whether a
// password is set, not what it is.

package client

import (
	"encoding/json"
	"strings"
	"unicode"
)

// redacted replaces every hidden value.
const redacted = "[REDACTED]"

// secretNameSuffixes end the normalized name of every field holding a secret.
var secretNameSuffixes = []string{"secret", "secretkey", "password", "token", "apikey", "privatekey"}

// credentialContainers are hidden whole, whatever they hold.
var credentialContainers = map[string]bool{"credential": true, "credentials": true}

// secretEndpointFields hold the secret itself on the secret endpoints.
var secretEndpointFields = []string{"defaultValue", "value"}

// normalizeName lowercases a field name and drops separators.
func normalizeName(name string) string {
	return strings.Map(func(r rune) rune {
		switch r {
		case '_', '-', '.', ' ':
			return -1
		}
		return unicode.ToLower(r)
	}, name)
}

// namesASecret reports whether a field of this name holds a secret.
func namesASecret(name string) bool {
	normalized := normalizeName(name)
	if credentialContainers[normalized] {
		return true
	}
	for _, suffix := range secretNameSuffixes {
		if strings.HasSuffix(normalized, suffix) {
			return true
		}
	}
	return false
}

// canHoldSecret reports whether a decoded JSON value could be a secret: a
// boolean, a number or null cannot.
func canHoldSecret(value interface{}) bool {
	switch value.(type) {
	case bool, float64, json.Number, nil:
		return false
	}
	return true
}

// hidesValue reports whether redactJSON hides the value of field name.
func hidesValue(name string, value interface{}) bool {
	return canHoldSecret(value) && namesASecret(name)
}

// isCredentialPair reports whether obj is a {key, value} pair, such as a header
// or a query parameter, whose key names a credential.
func isCredentialPair(obj map[string]interface{}) bool {
	key, ok := obj["key"].(string)
	if !ok {
		return false
	}
	if _, hasValue := obj["value"]; !hasValue {
		return false
	}
	return isSensitiveHeader(key) || namesASecret(key)
}

// isSecretEndpoint reports whether path is one of the secret endpoints, such
// as /v2/stable/secret or /v1/stable/secret/{secretID}/value.
func isSecretEndpoint(path string) bool {
	for _, segment := range strings.Split(path, "/") {
		if segment == "secret" {
			return true
		}
	}
	return false
}

// redactRequestBody is redactBody for a request to path. On the secret
// endpoints it also hides the generic fields that carry the secret itself.
func redactRequestBody(path string, body []byte) string {
	if !isSecretEndpoint(path) {
		return redactBody(body)
	}
	var fields map[string]interface{}
	if err := json.Unmarshal(body, &fields); err != nil {
		return redactBody(body)
	}
	for _, name := range secretEndpointFields {
		if value, ok := fields[name]; ok && canHoldSecret(value) {
			fields[name] = redacted
		}
	}
	hidden, err := json.Marshal(fields)
	if err != nil {
		return redactBody(body)
	}
	return redactBody(hidden)
}
